"""Database layer: connection handling and schema for the mini LMS."""

import sqlite3

SCHEMA = """
CREATE TABLE IF NOT EXISTS students (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    name    TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS assignments (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    name           TEXT NOT NULL UNIQUE,
    category       TEXT NOT NULL CHECK (category IN ('homework', 'project')),
    possible_points REAL NOT NULL CHECK (possible_points > 0)
);

CREATE TABLE IF NOT EXISTS submissions (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id     INTEGER NOT NULL REFERENCES students(id),
    assignment_id  INTEGER NOT NULL REFERENCES assignments(id),
    submitted_at   TEXT NOT NULL,
    content        TEXT NOT NULL,
    -- at most one live submission per (student, assignment)
    UNIQUE (student_id, assignment_id)
);

CREATE TABLE IF NOT EXISTS grades (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    submission_id  INTEGER NOT NULL UNIQUE REFERENCES submissions(id),
    points         REAL NOT NULL CHECK (points >= 0),
    graded_at      TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_submissions_student ON submissions(student_id);
CREATE INDEX IF NOT EXISTS idx_grades_submission ON grades(submission_id);
"""


def connect(path: str) -> sqlite3.Connection:
    """Open a connection to the LMS database with sane defaults."""
    conn = sqlite3.connect(path, isolation_level=None)  # autocommit; explicit BEGIN
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db(conn: sqlite3.Connection) -> None:
    """Create the schema if it does not exist yet."""
    conn.executescript(SCHEMA)

